# PostgreSQL Connection Pool in Node.js

## Installation

```bash
npm install pg
```

## Basic Pool Setup

```javascript
// db/pool.js
const { Pool } = require('pg');

const pool = new Pool({
  // Connection settings
  host: process.env.DB_HOST || 'localhost',
  port: process.env.DB_PORT || 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool sizing
  max: 20,                    // Maximum connections in pool
  min: 2,                     // Minimum idle connections to maintain
  idleTimeoutMillis: 30000,   // Close idle connections after 30s
  connectionTimeoutMillis: 5000, // Fail if can't connect within 5s

  // Query timeout (requires pg >= 8.x)
  statement_timeout: 10000,   // Kill queries running over 10s
  query_timeout: 10000,       // Timeout for query execution

  // SSL (for production)
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: true, ca: process.env.DB_SSL_CERT }
    : false,
});

module.exports = pool;
```

## Pool Event Handlers

```javascript
// db/pool.js (continued)

// Log when new connections are created
pool.on('connect', (client) => {
  console.log('New client connected to PostgreSQL');

  // Set session-level settings on each new connection
  client.query('SET timezone = "UTC"');
});

// Log when connections are acquired from pool
pool.on('acquire', (client) => {
  console.debug('Client acquired from pool');
});

// Critical: handle background errors on idle clients
pool.on('error', (err, client) => {
  console.error('Unexpected error on idle client:', err);
  // Don't crash the server - log and continue
  // Consider alerting your monitoring system here
});

// Log when connections are removed
pool.on('remove', (client) => {
  console.log('Client removed from pool');
});
```

## Query Helper with Error Handling

```javascript
// db/query.js
const pool = require('./pool');

/**
 * Execute a query with automatic connection management
 */
async function query(text, params) {
  const start = Date.now();

  try {
    const result = await pool.query(text, params);

    const duration = Date.now() - start;
    if (duration > 1000) {
      console.warn('Slow query detected:', { text, duration, rows: result.rowCount });
    }

    return result;
  } catch (err) {
    console.error('Query error:', {
      message: err.message,
      query: text,
      params,
      code: err.code,  // PostgreSQL error code
    });
    throw err; // Re-throw for caller to handle
  }
}

/**
 * Get a dedicated client for transactions
 */
async function getClient() {
  const client = await pool.connect();

  // Wrap release to add safety timeout
  const originalRelease = client.release.bind(client);
  const timeout = setTimeout(() => {
    console.error('Client checked out for too long - force releasing');
    originalRelease();
  }, 30000); // Force release after 30s

  client.release = () => {
    clearTimeout(timeout);
    originalRelease();
  };

  return client;
}

module.exports = { query, getClient };
```

## Transaction Helper

```javascript
// db/transaction.js
const { getClient } = require('./query');

/**
 * Execute multiple queries in a transaction
 * Automatically handles commit/rollback
 */
async function withTransaction(callback) {
  const client = await getClient();

  try {
    await client.query('BEGIN');

    const result = await callback(client);

    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    console.error('Transaction rolled back:', err.message);
    throw err;
  } finally {
    client.release(); // Always release back to pool
  }
}

module.exports = { withTransaction };
```

## Usage Examples

```javascript
// Simple query
const { query } = require('./db/query');
const { withTransaction } = require('./db/transaction');

// Basic query
async function getUser(id) {
  const { rows } = await query(
    'SELECT * FROM users WHERE id = $1',
    [id]
  );
  return rows[0] ?? null;
}

// Transaction example
async function transferFunds(fromId, toId, amount) {
  return withTransaction(async (client) => {
    // Both queries use the same connection/transaction
    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );

    const { rows } = await client.query(
      'SELECT balance FROM accounts WHERE id = $1',
      [fromId]
    );

    if (rows[0].balance < 0) {
      throw new Error('Insufficient funds'); // Triggers rollback
    }

    return { success: true };
  });
}
```

## Graceful Shutdown

```javascript
// server.js
const pool = require('./db/pool');

async function shutdown(signal) {
  console.log(`Received ${signal}, shutting down gracefully`);

  try {
    await pool.end(); // Wait for active queries, then close all connections
    console.log('Pool has ended');
    process.exit(0);
  } catch (err) {
    console.error('Error during pool shutdown:', err);
    process.exit(1);
  }
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
```

## Health Check Endpoint

```javascript
// routes/health.js
const pool = require('./db/pool');

async function healthCheck(req, res) {
  try {
    const { rows } = await pool.query('SELECT NOW() as time');

    res.json({
      status: 'healthy',
      database: 'connected',
      timestamp: rows[0].time,
      pool: {
        total: pool.totalCount,
        idle: pool.idleCount,
        waiting: pool.waitingCount,
      },
    });
  } catch (err) {
    res.status(503).json({
      status: 'unhealthy',
      database: 'disconnected',
      error: err.message,
    });
  }
}
```

## Key Configuration Guidelines

| Setting | Development | Production |
|---|---|---|
| `max` | 5–10 | 10–25 (tune per load) |
| `min` | 0–2 | 2–5 |
| `idleTimeoutMillis` | 10,000 | 30,000 |
| `connectionTimeoutMillis` | 3,000 | 5,000 |
| `statement_timeout` | 30,000 | 10,000 |

**Critical rules:**
- Always use `try/finally` to ensure `client.release()` is called
- Never call `pool.end()` between requests — only on shutdown
- Use `$1, $2` parameterized queries to prevent SQL injection
- Monitor `pool.waitingCount` — if consistently > 0, increase `max` or optimize queries
